describe('Accessibility attributes for login fields and product images', () => {
    beforeEach(() => {
        cy.visit('https://www.saucedemo.com');
    });

    it('should have non-empty placeholder attributes for login fields', () => {
        cy.get('[data-test="username"]').should('have.attr', 'placeholder').and('not.be.empty');
        cy.get('[data-test="password"]').should('have.attr', 'placeholder').and('not.be.empty');
    });

    it('should have non-empty alt attributes for product images after logging in', () => {
        cy.get('[data-test="username"]').type('standard_user');
        cy.get('[data-test="password"]').type('secret_sauce');
        cy.get('[data-test="login-button"]').click();

        cy.get('.inventory_item img.inventory_item_img').each(($img) => {
            cy.wrap($img).should('have.attr', 'alt').and('not.be.empty');
        });
    });
});
